content:
{
    "criteria": [
        {
            "id": "C1",
            "section": "合同主体审查",
            "criterion": "核实签约主体合法性与信息一致性",
            "check_points": [
                "通过国家企业信用信息公示系统等权威工商数据库核查该主体是否存在未结重大涉法涉诉案件（如被执行、失信、严重违法、股权冻结等）",
                "核对营业执照记载的经营范围，确认合同项下标的（尤其服务内容或产品类型）属于其登记经营范围之内",
                "逐项比对合同首部列明的主体信息（名称、统一社会信用代码、注册地址、联系地址、联系电话、传真、法定代表人/负责人姓名及职务、指定联系人及联系方式）与最新工商登记信息是否完全一致",
                "如合同涉及软件采购或技术产品，核查卖方是否拥有该软件/产品的核心知识产权（如著作权登记证书、专利证书、授权链文件），或明确约定知识产权归属及使用权限"
            ]
        },
        {
            "id": "C2",
            "section": "合同框架完整性审查",
            "criterion": "确保合同核心条款要素齐全、逻辑闭环、权责清晰",
            "check_points": [
                "检查合同是否完整包含以下必备条款：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权归属与使用约定、产品质量/服务标准保证条款、交付方式与时间、验收标准与程序、完成时限（含关键里程碑）、违约责任（含违约金计算方式与上限）、司法管辖法院/仲裁机构、不可抗力定义与处理机制、廉洁承诺条款、合同变更程序、合同份数及效力说明、电子送达效力约定",
                "确认合同中已明确指定主要项目负责人，并完整载明其姓名、身份证号码（或统一社会信用代码，如为单位）、联系电话及授权范围",
                "核查采购内容描述是否具体可执行：包括但不限于产品/服务品种、规格、型号、等级、花色、技术参数等；如内容复杂，是否通过附件形式予以详尽列明并注明‘附件为本合同不可分割组成部分’",
                "核验合同金额表述是否准确无歧义：数量单位、单价、总价、币种（如人民币/USD）须全部载明；大小写金额须完全一致；总价构成（含税/不含税）及税种、税率应明确；若含分项报价，各子项合计须等于合同总额",
                "审查付款计划是否具备可操作性：是否设置与履约进度挂钩的明确付款节点（如预付款、到货款、验收款、质保金）；质保金比例是否合理（通常不低于5%），是否约定于免费维保期届满后支付；是否明确每次付款前提（如发票类型：增值税专用发票/普通发票、开票时间、开票信息）"
            ]
        },
        {
            "id": "C3",
            "section": "合同期限与时间表述审查",
            "criterion": "确保期限约定精确、无歧义，符合实务执行要求",
            "check_points": [
                "合同是否明确约定起止日期（年月日），或以事件触发（如‘自双方签字盖章之日起生效’）；履行期限是否以具体时间单位（自然日/工作日）清晰界定",
                "若采用‘季度’‘年度’等周期表述，是否明确定义计算方式（例如：‘自然季度’或‘自起始日起每满三个月为一个季度’）；若涉及‘第X日’，是否注明系‘自然日’或‘工作日’",
                "关键时间节点（如交付日、验收截止日、质保期起算日）是否与合同其他条款（如付款节点、违约起算点）逻辑自洽、无冲突"
            ]
        },
        {
            "id": "C4",
            "section": "文本规范性与一致性审查",
            "criterion": "保障合同语言严谨、格式统一、内外一致",
            "check_points": [
                "全文通读排查错别字、标点误用、语法错误、语义模糊或逻辑矛盾等文字性瑕疵",
                "核对合同正文与所有附件（含技术规格书、服务清单、报价明细、廉洁协议等）中相同条款（如验收标准、付款条件、知识产权归属、违约责任）表述是否完全一致；不一致处须标注并提示修订",
                "全面筛查合同文本中是否残留招标文件、谈判纪要、框架协议等前置流程中的特定用语（如‘投标单位’‘竞谈供应商’‘原框架协议项下’），须统一替换为本合同适配表述（如‘乙方’‘甲方’‘本合同’）",
                "严格比对合同首部‘甲方/乙方’全称、签署页‘甲方（盖章）’‘乙方（盖章）’落款名称、骑缝章处名称、附件抬头名称，确保全程名称完全一致，无缩写、错字、漏字或括号差异",
                "核查所援引法律法规名称、条款序号是否准确有效（如《民法典》第五百零九条而非《合同法》），且现行有效（非已废止法律）",
                "确认合同正文末尾是否规范载明‘以下为合同签署栏’或‘以下无正文’字样，避免签署栏与正文内容混排导致效力争议"
            ]
        }
    ]
}
